const lessons=[{"sentences":[{"speaker":"A","text":"We really need to book our tickets for the summer concert before everything sells out.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.198291666666667},{"speaker":"B","text":"I checked the seating chart yesterday because I wanted to find the best possible view.","position":2,"audioStartSeconds":5.398291666666666,"audioEndSeconds":10.4935},{"speaker":"A","text":"Do you prefer sitting right near the front where we can see the musicians clearly?","position":3,"audioStartSeconds":10.6935,"audioEndSeconds":15.269041666666666},{"speaker":"B","text":"Front row seats are usually amazing, although they cost much more than our budget allows.","position":4,"audioStartSeconds":15.469041666666667,"audioEndSeconds":20.907958333333333},{"speaker":"A","text":"How much extra do those premium seats cost compared to the ones in the middle?","position":5,"audioStartSeconds":21.107958333333332,"audioEndSeconds":25.966166666666666},{"speaker":"B","text":"They are nearly double the price because you get free backstage access with them.","position":6,"audioStartSeconds":26.166166666666665,"audioEndSeconds":30.895541666666666},{"speaker":"A","text":"That is far too expensive for us since we only wanted standard entry tickets.","position":7,"audioStartSeconds":31.095541666666666,"audioEndSeconds":36.22441666666667},{"speaker":"B","text":"What about the balcony section if we want something cheaper yet still reasonably high up?","position":8,"audioStartSeconds":36.424416666666666,"audioEndSeconds":41.60483333333333},{"speaker":"A","text":"Balcony seats offer a broad view of the stage, but the distance might feel annoying.","position":9,"audioStartSeconds":41.804833333333335,"audioEndSeconds":47.23008333333333},{"speaker":"B","text":"My cousin sat there last month and complained that the performers looked extremely tiny.","position":10,"audioStartSeconds":47.430083333333336,"audioEndSeconds":52.67491666666667},{"speaker":"A","text":"We should avoid the balcony then because seeing their facial expressions matters to me.","position":11,"audioStartSeconds":52.874916666666664,"audioEndSeconds":58.042458333333336},{"speaker":"B","text":"Rows twenty through thirty in the ground section seem like a very sensible compromise.","position":12,"audioStartSeconds":58.24245833333333,"audioEndSeconds":63.564625},{"speaker":"A","text":"Are those middle rows affordable and do they provide a decent angle of the stage?","position":13,"audioStartSeconds":63.764625,"audioEndSeconds":68.481125},{"speaker":"B","text":"They cost a reasonable amount and sit directly opposite the main microphone stands.","position":14,"audioStartSeconds":68.681125,"audioEndSeconds":73.91308333333333},{"speaker":"A","text":"Let us purchase two tickets in row twenty five before anyone else takes them.","position":15,"audioStartSeconds":74.11308333333334,"audioEndSeconds":79.18729166666667},{"speaker":"B","text":"I will open the payment page right now and complete our booking transaction securely.","position":16,"audioStartSeconds":79.38729166666667,"audioEndSeconds":84.63095833333334}],"questions":[{"prompt":"What is the primary purpose of the conversation?","options":["To select concert seats based on price and visibility.","To complain about the rising cost of live music.","To request a refund for previously purchased tickets."],"answer":"A","evidenceSentence":1,"evidence":"We really need to book our tickets for the summer concert","explanation":"Hai người bạn đang bàn về việc đặt vé và chọn chỗ ngồi cho buổi hòa nhạc."},{"prompt":"Why do the speakers reject the front row seats?","options":["Because they are already completely sold out.","Because they exceed the budget of the friends.","Because the view of the stage is blocked."],"answer":"B","evidenceSentence":4,"evidence":"Front row seats are usually amazing, although they cost much more than our budget allows.","explanation":"Ghế hàng đầu quá đắt đỏ so với ngân sách của họ."},{"prompt":"What benefit is included with the most expensive premium seats?","options":["A complimentary dinner after the show.","Free backstage access with the performers.","Signed merchandise from the lead singer."],"answer":"B","evidenceSentence":6,"evidence":"free backstage access with them","explanation":"Vé đắt tiền đi kèm quyền vào hậu trường miễn phí."},{"prompt":"What did B's cousin say about the balcony section?","options":["The sound quality was too loud to enjoy.","The performers appeared extremely small from there.","The area was overcrowded with noisy people."],"answer":"B","evidenceSentence":10,"evidence":"performers looked extremely tiny","explanation":"Họ hàng của B phàn nàn rằng nhìn nghệ sĩ từ ban công rất nhỏ."},{"prompt":"What location do the friends finally agree upon?","options":["The balcony section near the back wall.","The front row directly beneath the speakers.","The ground section in the middle rows."],"answer":"C","evidenceSentence":12,"evidence":"Rows twenty through thirty in the ground section seem like a very sensible compromise.","explanation":"Họ chọn các hàng ghế giữa từ 20 đến 30 dưới tầng chính làm giải pháp thỏa hiệp."},{"prompt":"What action will speaker B take next?","options":["Open the payment page and finish the booking.","Call the customer service hotline for assistance.","Walk down to the physical box office location."],"answer":"A","evidenceSentence":16,"evidence":"open the payment page right now and complete our booking transaction","explanation":"B sẽ mở trang thanh toán để hoàn tất giao dịch đặt vé ngay lập tức."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
